package edu.campus.studyroom.user.dto;

import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.Pattern;
import jakarta.validation.constraints.Size;

/**
 * Admin creates a student account. The account is normalized (trim + upper-case)
 * server-side before the duplicate check and the insert; the role is never taken
 * from the client. The initial one-time password is generated by the server and
 * returned once in the create response.
 */
public record CreateStudentRequest(
        @NotBlank @Pattern(regexp = "^[A-Za-z0-9]{4,32}$",
                message = "学号须为 4—32 位字母或数字") String account,
        @NotBlank @Size(max = 64, message = "姓名不能超过 64 字") String name,
        @Size(max = 100, message = "学院不能超过 100 字") String college
) {
}
